package com.minhaempresa.recrutamentoapi.shared.persistence;

import jakarta.persistence.Column;
import jakarta.persistence.Id;
import jakarta.persistence.MappedSuperclass;
import java.util.UUID;
import lombok.Getter;
import org.hibernate.annotations.UuidGenerator;
import org.hibernate.proxy.HibernateProxy;

/**
 * Base class of every entity: a UUID v7 identifier (time-ordered, index friendly) generated by
 * Hibernate on persist.
 *
 * <p>{@code equals}/{@code hashCode} use only the id (and the real class, unwrapping Hibernate proxies);
 * {@code toString} never includes relationships.
 */
@Getter
@MappedSuperclass
public abstract class BaseEntity {

    @Id
    @UuidGenerator(style = UuidGenerator.Style.VERSION_7)
    @Column(name = "id", nullable = false, updatable = false)
    private UUID id;

    @Override
    public final boolean equals(Object other) {
        if (this == other) {
            return true;
        }
        if (other == null || effectiveClass(this) != effectiveClass(other)) {
            return false;
        }
        UUID otherId = ((BaseEntity) other).getId();
        return id != null && id.equals(otherId);
    }

    @Override
    public final int hashCode() {
        // Constant per class: stays the same before and after the id is assigned
        return effectiveClass(this).hashCode();
    }

    @Override
    public String toString() {
        return effectiveClass(this).getSimpleName() + "(id=" + id + ")";
    }

    private static Class<?> effectiveClass(Object entity) {
        return entity instanceof HibernateProxy proxy
                ? proxy.getHibernateLazyInitializer().getPersistentClass()
                : entity.getClass();
    }
}
